DROP TABLE IF EXISTS `audit_logs`;
CREATE TABLE `audit_logs` (
  `audit_log_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `event_type` varchar(120) NOT NULL,
  `module` varchar(120) NOT NULL,
  `description` varchar(500) NOT NULL,
  `status` enum('info','success','failure','attempt') NOT NULL DEFAULT 'info',
  `actor_type` enum('admin','student','guest','system') NOT NULL DEFAULT 'guest',
  `actor_id` int(11) DEFAULT NULL,
  `actor_name` varchar(255) DEFAULT NULL,
  `target_type` varchar(80) DEFAULT NULL,
  `target_id` varchar(120) DEFAULT NULL,
  `request_method` varchar(10) NOT NULL,
  `request_uri` varchar(500) NOT NULL,
  `ip_address` varchar(45) NOT NULL,
  `user_agent` varchar(500) DEFAULT NULL,
  `metadata` longtext DEFAULT NULL,
  `old_values` longtext DEFAULT NULL,
  `new_values` longtext DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`audit_log_id`),
  KEY `idx_audit_created_at` (`created_at`),
  KEY `idx_audit_actor` (`actor_type`,`actor_id`),
  KEY `idx_audit_event_type` (`event_type`),
  KEY `idx_audit_module` (`module`),
  KEY `idx_audit_status` (`status`),
  KEY `idx_audit_login_security` (`module`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2187 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `backup_history`;
CREATE TABLE `backup_history` (
  `backup_id` int(11) NOT NULL AUTO_INCREMENT,
  `filename` varchar(255) DEFAULT NULL,
  `action` enum('backup','restore') NOT NULL DEFAULT 'backup',
  `file_size` bigint(20) unsigned DEFAULT NULL,
  `status` enum('started','success','failed') NOT NULL DEFAULT 'started',
  `created_by` int(11) DEFAULT NULL,
  `created_by_name` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `completed_at` timestamp NULL DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `notes` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`backup_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `book_reservations`;
CREATE TABLE `book_reservations` (
  `reservation_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `student_id` int(11) NOT NULL,
  `book_id` int(11) NOT NULL,
  `status` enum('pending','ready','fulfilled','cancelled') NOT NULL DEFAULT 'pending',
  `reserved_at` datetime NOT NULL DEFAULT current_timestamp(),
  `ready_at` datetime DEFAULT NULL,
  `fulfilled_at` datetime DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `notes` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`reservation_id`),
  KEY `idx_reservation_student_status` (`student_id`,`status`),
  KEY `idx_reservation_book_status` (`book_id`,`status`),
  KEY `idx_reservation_queue` (`book_id`,`status`,`reserved_at`),
  CONSTRAINT `fk_reservation_book` FOREIGN KEY (`book_id`) REFERENCES `books` (`book_id`),
  CONSTRAINT `fk_reservation_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`student_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `books`;
CREATE TABLE `books` (
  `book_id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `author` varchar(255) NOT NULL,
  `co_authors` text DEFAULT NULL,
  `place_of_publication` varchar(255) DEFAULT NULL,
  `publication_date` date DEFAULT NULL,
  `book_number` varchar(100) NOT NULL,
  `book_pages` int(11) NOT NULL,
  `source_of_funds` varchar(255) DEFAULT NULL,
  `cost_price` decimal(10,2) DEFAULT NULL,
  `publisher` varchar(255) DEFAULT NULL,
  `edition` varchar(100) DEFAULT NULL,
  `volumes` varchar(100) DEFAULT NULL,
  `class` varchar(100) DEFAULT NULL,
  `type_of_material` varchar(100) DEFAULT NULL,
  `location_collection` varchar(255) DEFAULT NULL,
  `library_building` varchar(150) DEFAULT NULL,
  `shelf_number` varchar(100) DEFAULT NULL,
  `library_section` varchar(150) DEFAULT NULL,
  `qr_code` varchar(255) NOT NULL,
  `book_status` enum('available','out_of_stock','damaged','lost') NOT NULL DEFAULT 'available',
  `book_condition` enum('Excellent','Good','Fair','Damaged','Lost') NOT NULL DEFAULT 'Good',
  `is_archived` tinyint(1) NOT NULL DEFAULT 0,
  `archived_at` datetime DEFAULT NULL,
  `archived_by` int(11) DEFAULT NULL,
  `total_copies` int(11) NOT NULL DEFAULT 1,
  `available_copies` int(11) NOT NULL DEFAULT 1,
  `borrowed_copies` int(11) NOT NULL DEFAULT 0,
  `lost_copies` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`book_id`),
  UNIQUE KEY `uq_books_qr_code` (`qr_code`),
  UNIQUE KEY `uq_books_book_number` (`book_number`),
  KEY `idx_books_status` (`book_status`),
  KEY `idx_books_title` (`title`),
  KEY `idx_books_author` (`author`),
  KEY `idx_books_archived` (`is_archived`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


